313	/// `panopt _process-report` - report runtime facts for an instance.
314	///
315	/// The cockpit plugin shells this after it reconciles a `starting` row into a
316	/// pane, to hand the daemon the Zellij pane id it landed in (the pid is
317	/// reported separately by the in-pane wrapper). Best-effort, like
318	/// [`crate::agent::leave`]: a missing daemon is logged by the caller, not
319	/// surfaced.
320	pub fn exec_report(
321	    ws: Option<PathBuf>,
322	    id: u64,
323	    pane_id: Option<String>,
324	    agent_state: Option<String>,
325	    port: u16,
326	) -> Result<()> {
327	    daemon::ensure(None, port)?;
328	    let client = Client::connect(&observer_url(ws, port)?)?;
329	    let mut args = Map::new();
330	    args.insert("process_id".into(), json!(id));
331	    insert_opt(&mut args, "pane_id", pane_id);
332	    insert_opt(&mut args, "agent_state", agent_state);
333	    let result = client.call("process_report", Value::Object(args));
334	    client.close();
335	    result
336	        .map(|_| ())
337	        .context("reporting process runtime facts")
338	}
339	
340	/// `panopt _input-ack` - ack a delivered queued input (todo #160).
341	///
342	/// The cockpit plugin shells this after it writes a queued input into an agent's
343	/// pane, so the daemon stamps the row delivered and drops it from
344	/// `inputs.jsonl`. Best-effort, like [`exec_report`]: a failure just leaves the
345	/// input in the queue, where the next poll re-attempts delivery.
346	pub fn exec_input_ack(ws: Option<PathBuf>, seq: i64, port: u16) -> Result<()> {
347	    daemon::ensure(None, port)?;
348	    let client = Client::connect(&observer_url(ws, port)?)?;
349	    let result = client.call("input_ack", json!({ "seq": seq }));
350	    client.close();
