fn parses_type_state_agent_and_idle_segments() {
    let row = parse_process_line(
        "- [agent] #5 Mediator (from #3) · running · type:claude-code · agent:mediator-1a · state:idle · idle:2m",
    )
    .unwrap();
    assert_eq!(row.label, "Mediator");
