    assert_eq!(strip_trailing_id("good-224", 224), "good");
    assert_eq!(strip_trailing_id("verify-submit #220", 220), "verify-submit");
    assert_eq!(strip_trailing_id("weather-portland #193", 193), "weather-portland");
